-- BrandKraf — BM translation batch 19: FULL-DEPTH (5 articles, net-new). Run AFTER blog-i18n-migration.sql.
-- Faithful, section-for-section translations of the English articles. Content dollar-quoted ($ms$...$ms$).

update public.blog_posts set
  title_ms = 'Cara Membuat Video Jenama yang Orang Ingati',
  excerpt_ms = 'Video jenama menceritakan kisah anda dan membuatkan orang merasai sesuatu. Pelajari cara mencipta video jenama yang membina hubungan, kepercayaan, dan pengiktirafan — melangkaui sekadar menjual.',
  content_ms = $ms$<p>Tidak setiap video patut menjual secara langsung. Video jenama menceritakan kisah anda, menyampaikan nilai anda, dan membuatkan orang merasai sesuatu — membina hubungan emosi yang menukar pelanggan menjadi peminat setia. Inilah cara membuat video jenama yang berbaloi diingati.</p>
<blockquote>Video produk memenangi jualan. Video jenama memenangi hubungan — dan hubungan itu yang memastikan pelanggan terus kembali.</blockquote>
<h2>Untuk apa video jenama</h2>
<p>Video jenama menyampaikan siapa anda, apa yang anda perjuangkan, dan mengapa anda wujud — bukan hanya apa yang anda jual. Matlamatnya ialah hubungan dan pengiktirafan, membina kepercayaan dan kasih sayang yang menjadikan semua pemasaran anda yang lain lebih berkesan. Fikir emosi dan kisah berbanding ciri.</p>
<h2>Pimpin dengan kisah dan emosi</h2>
<p>Video jenama paling diingati menceritakan kisah manusia dan membuatkan penonton merasai sesuatu — inspirasi, kepunyaan, jenaka, atau kebanggaan. Orang mengingati bagaimana anda membuatkan mereka rasa jauh lebih lama daripada mana-mana dakwaan produk. Putuskan emosi yang anda mahu cetuskan, kemudian bina kisah sekitarnya.</p>
<h2>Tunjukkan mengapa dan nilai anda</h2>
<p>Pelanggan semakin memilih jenama yang nilainya sejajar dengan mereka. Video jenama ialah tempat sempurna untuk berkongsi tujuan anda, kisah asal usul anda, dan apa yang anda percaya — secara autentik. Ini <a href="/ms/blog/branding-101-build-a-brand">penjenamaan</a> dipacu penceritaan dalam gerakan.</p>
<h2>Paparkan orang sebenar</h2>
<p>Pengasas, ahli pasukan, dan pelanggan sebenar menjadikan video jenama autentik dan relatable. Orang berhubung dengan orang, jadi biarkan wajah dan suara tulen membawa kisah anda dan bukannya naratif korporat tanpa wajah. Keaslian ialah keseluruhan intinya.</p>
<h2>Kekalkan ia sesuai jenama</h2>
<p>Video jenama anda patut kelihatan dan terasa jelas seperti anda — warna, nada, muzik, dan gaya yang konsisten. Ini mengukuhkan pengiktirafan dan mengikat video kepada identiti jenama anda yang lebih luas. Kekonsistenan yang menjadikan jenama mudah diingati merentasi setiap titik sentuh.</p>
<h2>Gunakannya untuk menambat kehadiran anda</h2>
<p>Paparkan video jenama anda di laman utama, halaman Tentang, profil sosial, dan dek pitching. Ia teras yang memperkenalkan jenama anda dan menetapkan nada untuk segala yang lain. Satu video jenama yang kukuh bekerja keras merentasi keseluruhan kehadiran anda — dan mengikat kepada penceritaan perayaan dan bermusim seperti <a href="/ms/blog/hari-raya-marketing-playbook">buku panduan Hari Raya</a> kami.</p>
<h2>Soalan lazim</h2>
<h3>Apa beza video jenama dengan video produk?</h3>
<p>Video produk menjual produk tertentu; video jenama membina hubungan emosi dan menyampaikan siapa anda dan apa yang anda perjuangkan.</p>
<h3>Berapa panjang video jenama patut?</h3>
<p>Selalunya 60 hingga 120 saat — cukup panjang untuk menceritakan kisah, cukup pendek untuk mengekalkan perhatian. Emosi lebih penting daripada panjang.</p>
<h3>Adakah video jenama memacu jualan?</h3>
<p>Secara tidak langsung tetapi berkuasa — ia membina kepercayaan dan kasih sayang yang menjadikan setiap usaha pemasaran lain menukar lebih baik dan meningkatkan kesetiaan.</p>
<h3>Adakah saya perlukan bajet besar untuk video jenama?</h3>
<p>Kisah yang kukuh lebih penting daripada bajet. Walaupun video jenama yang ringkas dan autentik dengan orang sebenar boleh sangat berkesan.</p>
<p>BrandKraf mencipta video jenama yang rakyat Malaysia ingati. Terokai <a href="/ms/guides/video-marketing">panduan pemasaran video</a> kami, <a href="/ms/portfolio/branding-creative">perkhidmatan penjenamaan</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'corporate-brand-video-guide';

update public.blog_posts set
  title_ms = 'Analitik Pemasaran: Cara Mengukur Apa yang Benar-benar Berkesan',
  excerpt_ms = 'Pemasaran tanpa pengukuran ialah tekaan. Pelajari asas analitik pemasaran — apa yang perlu dijejaki, alat yang perlu digunakan, dan cara menukar data menjadi keputusan lebih baik.',
  content_ms = $ms$<p>Separuh daripada semua bajet pemasaran terbazir — masalahnya ialah mengetahui separuh yang mana. Analitik pemasaran ialah cara anda mengetahui. Dengan mengukur apa yang berkesan dan apa yang tidak, anda berhenti meneka dan mula melabur di tempat ia membuahkan hasil. Inilah cara mendapatkan analitik dengan betul tanpa lemas dalam data.</p>
<blockquote>Anda tidak boleh memperbaiki apa yang anda tidak ukur. Tetapi anda juga tidak boleh bertindak atas data yang anda tidak pernah lihat.</blockquote>
<h2>Mengapa analitik pemasaran penting</h2>
<p>Analitik menukar pemasaran daripada kos menjadi pelaburan yang boleh anda optimumkan. Ia memberitahu anda saluran mana memacu jualan, kandungan mana beresonansi, dan di mana wang terbazir — supaya anda boleh menggandakan apa yang berfungsi dan memotong apa yang tidak. Tanpanya, anda terbang buta.</p>
<h2>Mula dengan soalan yang betul</h2>
<p>Jangan mula dengan data — mula dengan soalan. Saluran mana membawa paling banyak pelanggan? Berapa kos untuk memperoleh seorang? Kandungan mana menukar? Soalan yang jelas memberitahu anda apa yang perlu diukur, jadi anda mengumpul pandangan dan bukannya kebisingan.</p>
<h2>Perkara teras untuk diukur</h2>
<ul><li><strong>Trafik dan sumber</strong> — dari mana pelawat datang.</li><li><strong>Penukaran</strong> — tindakan yang penting (jualan, petunjuk).</li><li><strong>Kos sepemerolehan dan ROI</strong> — apa kos dan pulangan pemasaran.</li><li><strong>Penglibatan dan pengekalan</strong> — cara penonton berinteraksi dan kekal.</li></ul>
<h2>Alat penting</h2>
<p>Kebanyakan perniagaan boleh meliputi asas dengan alat percuma: <a href="/ms/blog/ga4-analytics-beginners-guide">Google Analytics 4</a> untuk tingkah laku laman web, <a href="/ms/blog/google-search-console-guide">Google Search Console</a> untuk SEO, dan analitik natif dalam platform iklan dan sosial anda. Mula di situ sebelum membeli apa-apa yang mewah.</p>
<h2>Sambungkan data ke keputusan</h2>
<p>Data hanya bernilai jika ia mengubah apa yang anda lakukan. Setiap bulan, semak nombor anda, kenal pasti satu perkara yang berfungsi (buat lebih) dan satu yang tidak (betulkan atau potong). Gelung ringkas ini, diulang, berkompaun menjadi penambahbaikan serius dari masa ke masa.</p>
<h2>Jangan lemas dalam data</h2>
<p>Kesilapan analitik terbesar ialah menjejaki segala-galanya dan bertindak atas tiada. Fokus pada segelintir metrik yang dikaitkan dengan matlamat anda, bina <a href="/ms/blog/marketing-dashboard-guide">papan pemuka</a> ringkas, dan abaikan nombor kesombongan. Kejelasan mengalahkan kerumitan setiap kali.</p>
<h2>Soalan lazim</h2>
<h3>Alat analitik apa saya perlukan untuk bermula?</h3>
<p>Yang percuma meliputi kebanyakan keperluan: Google Analytics 4, Google Search Console, dan analitik platform iklan serta sosial anda. Tambah alat berbayar hanya apabila anda melangkaui ini.</p>
<h3>Apa perkara paling penting untuk diukur?</h3>
<p>Penukaran dan pulangan yang dijananya. Segala yang lain ialah konteks untuk menambah baik tindakan yang menjana wang itu.</p>
<h3>Berapa kerap saya patut menyemak analitik saya?</h3>
<p>Semakan bulanan yang fokus sudah cukup untuk kebanyakan perniagaan, dengan semakan pantas semasa kempen aktif.</p>
<h3>Saya rasa analitik membebankan — di mana saya mula?</h3>
<p>Mula dengan satu soalan (cth. "saluran mana memacu jualan?"), ukur itu sahaja, dan bertindak atasnya. Kembangkan secara beransur.</p>
<p>BrandKraf menukar data pemasaran menjadi pertumbuhan untuk jenama Malaysia. Terokai <a href="/ms/guides/marketing-analytics">panduan analitik pemasaran</a> kami, <a href="/ms/portfolio/ai-driven-marketing">perkhidmatan pemasaran AI</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'marketing-analytics-guide';

update public.blog_posts set
  title_ms = 'KPI dan Metrik Pemasaran yang Penting',
  excerpt_ms = 'Menjejaki metrik yang salah membazir masa. Pelajari KPI pemasaran yang benar-benar meramal pertumbuhan perniagaan — merentasi trafik, penukaran, kos, dan pengekalan.',
  content_ms = $ms$<p>Terdapat ratusan metrik pemasaran yang boleh anda jejaki — dan kebanyakannya ialah gangguan. Kuncinya ialah memfokus pada KPI (petunjuk prestasi utama) yang benar-benar meramal pertumbuhan perniagaan. Inilah yang penting, disusun supaya anda tahu apa yang perlu diperhatikan.</p>
<blockquote>Jika metrik tidak mengubah keputusan, berhenti menjejakinya. KPI ialah untuk tindakan, bukan hiasan.</blockquote>
<h2>Apa yang menjadikan metrik sebagai KPI</h2>
<p>KPI ialah metrik yang dikaitkan secara langsung dengan matlamat perniagaan. Suka dan pengikut ialah metrik; pelanggan diperoleh dan kos sepemerolehan ialah KPI. Ujiannya: jika nombor itu berubah, adakah anda akan melakukan sesuatu secara berbeza? Jika tidak, ia mungkin metrik kesombongan.</p>
<h2>KPI pemerolehan</h2>
<ul><li><strong>Trafik mengikut saluran</strong> — dari mana penonton datang.</li><li><strong>Kos sepetunjuk / sepemerolehan (CPL/CPA)</strong> — apa kos seorang pelanggan.</li><li><strong>Kadar penukaran</strong> — sebaik mana anda menukar pelawat menjadi pelanggan.</li></ul>
<h2>KPI hasil</h2>
<ul><li><strong>Pulangan atas perbelanjaan iklan (ROAS)</strong> — lihat <a href="/ms/blog/how-to-improve-roas">panduan ROAS</a> kami.</li><li><strong>Nilai sepanjang hayat pelanggan (LTV)</strong> — jumlah nilai pelanggan dari masa ke masa.</li><li><strong>Nisbah LTV kepada CAC</strong> — kesihatan enjin pertumbuhan anda; lihat <a href="/ms/blog/customer-acquisition-cost-guide">panduan CAC dan LTV</a> kami.</li></ul>
<h2>KPI penglibatan dan pengekalan</h2>
<p>Kadar penglibatan, kadar pembelian berulang, dan pemberhentian menunjukkan sama ada anda membina hubungan yang berkekalan atau sentiasa menggantikan pelanggan yang hilang. KPI pengekalan selalunya tempat keuntungan terbesar bersembunyi — lihat <a href="/ms/blog/customer-retention-loyalty-marketing">pengekalan pelanggan</a>.</p>
<h2>Padankan KPI dengan matlamat anda</h2>
<p>KPI anda patut mencerminkan apa yang penting sekarang. Perniagaan baharu fokus pada pemerolehan dan penukaran; yang matang pada LTV dan pengekalan. Pilih set yang fokus — segelintir, bukan lima puluh — yang memetakan kepada objektif semasa anda.</p>
<h2>Elakkan metrik kesombongan</h2>
<p>Pengikut, suka, dan tera berasa baik tetapi jarang meramal hasil. Ia mempunyai tempatnya sebagai isyarat sokongan, tetapi jangan sekali-kali biarkan ia menjadi papan markah utama anda. Nilai pemasaran berdasarkan pelanggan dan keuntungan, bukan tepukan — lihat <a href="/ms/blog/social-media-metrics-that-matter">metrik media sosial</a>.</p>
<h2>Soalan lazim</h2>
<h3>Apa beza metrik dengan KPI?</h3>
<p>Metrik ialah sebarang pengukuran; KPI ialah metrik yang dikaitkan dengan matlamat perniagaan utama. KPI memacu keputusan; kebanyakan metrik hanyalah konteks.</p>
<h3>Berapa KPI patut saya jejaki?</h3>
<p>Segelintir yang fokus yang memetakan kepada matlamat anda. Menjejaki terlalu banyak membawa kepada lumpuh dan bertindak atas tiada.</p>
<h3>Apa KPI pemasaran paling penting?</h3>
<p>Ia bergantung pada peringkat anda, tetapi kos sepemerolehan, ROAS, dan LTV-kepada-CAC antara yang paling memberitahu untuk pertumbuhan dan keuntungan.</p>
<h3>Adakah pengikut dan suka tidak berguna?</h3>
<p>Bukan tidak berguna, tetapi ia isyarat sokongan, bukan KPI teras. Jangan biarkan metrik kesombongan menjadi ukuran utama kejayaan anda.</p>
<p>BrandKraf melaporkan KPI yang penting untuk jenama Malaysia. Terokai <a href="/ms/guides/marketing-analytics">panduan analitik pemasaran</a> kami, <a href="/ms/portfolio/ai-driven-marketing">perkhidmatan pemasaran AI</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'marketing-kpis-to-track';

update public.blog_posts set
  title_ms = 'Cara Mengukur ROI Pemasaran Anda',
  excerpt_ms = 'Jika anda tidak boleh membuktikan pemasaran menjana wang, ia kelihatan seperti kos. Pelajari cara mengukur ROI pemasaran dengan betul supaya anda tahu dengan tepat apa yang berbaloi dibelanjakan.',
  content_ms = $ms$<p>Pemasaran patut menjana wang untuk anda, bukan hanya mengenakan kos — tetapi hanya pengukuran membuktikannya. Mengetahui ROI (pulangan atas pelaburan) pemasaran anda memberitahu anda apa yang berbaloi dilakukan lebih banyak dan apa yang perlu dipotong. Inilah cara mengukurnya dengan betul.</p>
<blockquote>Pemasaran yang anda tidak boleh ukur kelihatan seperti perbelanjaan. Pemasaran yang anda boleh ukur menjadi pelaburan yang anda kembangkan.</blockquote>
<h2>Apa maksud ROI pemasaran</h2>
<p>ROI pemasaran ialah pulangan yang anda peroleh untuk setiap ringgit yang dibelanjakan pada pemasaran. Formula asasnya ialah (hasil daripada pemasaran tolak kos pemasaran) dibahagi dengan kos pemasaran. ROI positif bermakna pemasaran membayar dirinya sendiri dan lebih; negatif bermakna anda kehilangan wang.</p>
<h2>Jejaki kos penuh</h2>
<p>ROI yang tepat memerlukan kos yang jujur — bukan hanya perbelanjaan iklan, tetapi alat, pengeluaran kandungan, dan masa atau yuran agensi. Mengurangkan kira kos menggelembungkan ROI anda dan membawa kepada keputusan buruk. Sertakan segala yang masuk ke dalam pemasaran.</p>
<h2>Atribusikan hasil dengan betul</h2>
<p>Bahagian sukar ialah menghubungkan hasil dengan pemasaran. Gunakan penjejakan penukaran, pautan UTM, dan alat seperti Google Analytics untuk mengesan usaha mana memacu jualan mana. Lihat panduan kami tentang <a href="/ms/blog/conversion-tracking-guide">penjejakan penukaran</a> dan <a href="/ms/blog/utm-tracking-guide">penjejakan UTM</a>. Tanpa atribusi, ROI ialah tekaan.</p>
<h2>Perhatikan jeda masa</h2>
<p>Tidak semua pemasaran membuahkan hasil serta-merta. SEO dan kandungan berkompaun selama berbulan-bulan; pembinaan jenama membayar balik perlahan-lahan. Nilai saluran bertindak pantas (seperti iklan) pada jangka masa pendek, tetapi beri pelaburan jangka panjang masa sebelum mengisytiharkannya kerugian.</p>
<h2>Ambil kira nilai sepanjang hayat</h2>
<p>Mengukur ROI pada satu pembelian mengurangkan nilai pemasaran yang memenangi pelanggan setia. Jika pelanggan membeli berulang kali, <a href="/ms/blog/customer-acquisition-cost-guide">nilai sepanjang hayat</a> mereka — bukan hanya jualan pertama — ialah pulangan sebenar. Ini selalunya mewajarkan berbelanja lebih untuk memperoleh pelanggan yang betul.</p>
<h2>Gunakan ROI untuk memperuntukkan bajet</h2>
<p>Tujuan mengukur ROI ialah tindakan: alihkan bajet ke arah saluran ROI tinggi dan jauh daripada yang ROI rendah. Semak secara kerap, dan biarkan data — bukan tabiat atau firasat — membimbing ke mana wang pemasaran anda pergi. Pasangkan ini dengan disiplin <a href="/ms/blog/how-to-improve-roas">ROAS</a> anda.</p>
<h2>Soalan lazim</h2>
<h3>Apa ROI pemasaran yang baik?</h3>
<p>Ia berbeza mengikut saluran dan industri, tetapi pulangan mesti melebihi kos anda (termasuk masa dan alat) dan mengambil kira nilai sepanjang hayat pelanggan untuk benar-benar positif.</p>
<h3>Apa beza ROI dengan ROAS?</h3>
<p>ROAS ialah hasil dibahagi perbelanjaan iklan; ROI mengambil kira semua kos dan keuntungan. ROI ialah gambaran yang lebih penuh dan benar tentang keuntungan.</p>
<h3>Bagaimana saya atribusikan jualan kepada pemasaran?</h3>
<p>Gunakan penjejakan penukaran, pautan UTM, dan alat analitik untuk mengesan saluran dan kempen mana memacu jualan mana.</p>
<h3>Mengapa ROI saya sukar diukur?</h3>
<p>Biasanya kerana penjejakan kos tidak lengkap, atribusi lemah, atau jeda masa. Betulkan penjejakan dahulu, dan beri saluran jangka panjang masa.</p>
<p>BrandKraf membantu jenama Malaysia membuktikan dan mengembangkan ROI pemasaran. Terokai <a href="/ms/guides/marketing-analytics">panduan analitik pemasaran</a> kami, <a href="/ms/portfolio/ai-driven-marketing">perkhidmatan pemasaran AI</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'how-to-measure-marketing-roi';

update public.blog_posts set
  title_ms = 'Google Search Console untuk Pemula',
  excerpt_ms = 'Google Search Console ialah alat percuma yang menunjukkan cara anda muncul dalam carian Google. Pelajari cara menyediakannya dan menggunakannya untuk mencari kata kunci, membetulkan isu, dan mengembangkan trafik organik.',
  content_ms = $ms$<p>Jika anda ambil berat tentang ditemui di Google, Google Search Console (GSC) adalah penting — dan percuma. Ia menunjukkan dengan tepat cara laman anda berprestasi dalam carian: apa yang anda dapat kedudukan, apa yang diklik, dan apa yang rosak. Inilah cara pemula boleh menggunakannya untuk mengembangkan trafik organik.</p>
<blockquote>Google Analytics memberitahu anda apa yang orang lakukan di laman anda. Search Console memberitahu anda cara mereka menemuinya sejak awal.</blockquote>
<h2>Apa yang Search Console tunjukkan anda</h2>
<p>GSC mendedahkan sisi carian laman anda: pertanyaan mana anda muncul, klik dan tera anda, kedudukan purata anda, halaman mana berprestasi, dan sebarang masalah teknikal atau pengindeksan. Ia perkara paling hampir untuk melihat laman anda melalui mata Google.</p>
<h2>Sediakan ia dahulu</h2>
<p>Tambah dan sahkan laman anda dalam GSC (persediaan sekali sahaja), kemudian serahkan <a href="/ms/blog/seo-sitemap">peta laman</a> anda supaya Google boleh mencari semua halaman anda. Ini membuka kunci data dan membantu Google merangkak laman anda dengan cekap. Ia mengambil masa beberapa minit dan ialah asas untuk kerja SEO.</p>
<h2>Cari peluang kata kunci</h2>
<p>Laporan Prestasi ialah emas. Ia menunjukkan carian sebenar yang membawa anda tera dan klik — termasuk istilah yang anda dapat kedudukan di halaman dua yang, dengan sedikit usaha, boleh mencapai halaman satu. Kata kunci hampir-terlepas ini antara kemenangan SEO paling mudah yang ada.</p>
<h2>Betulkan apa yang rosak</h2>
<p>GSC menanda isu pengindeksan, halaman yang Google tidak boleh rangkak, masalah kebolehgunaan mudah alih, dan lebih. Menangani ini memastikan kandungan anda benar-benar boleh mendapat kedudukan. Halaman yang Google tidak boleh indeks memperoleh sifar trafik, jadi membetulkan isu liputan ialah keutamaan tinggi.</p>
<h2>Minta pengindeksan halaman baharu</h2>
<p>Apabila anda menerbitkan atau mengemas kini halaman penting, gunakan alat Pemeriksaan URL untuk meminta pengindeksan — menolak Google untuk merangkaknya lebih cepat. Ini mempercepat betapa cepatnya kandungan baharu boleh mula mendapat kedudukan dan memperoleh trafik.</p>
<h2>Pasangkan ia dengan Analytics</h2>
<p>GSC menunjukkan cara orang menemui anda; <a href="/ms/blog/ga4-analytics-beginners-guide">Google Analytics</a> menunjukkan apa yang mereka lakukan seterusnya. Digunakan bersama, ia memberi perjalanan penuh daripada carian ke tindakan — asas SEO dipacu data. Kedua-duanya percuma dan penting.</p>
<h2>Soalan lazim</h2>
<h3>Adakah Google Search Console percuma?</h3>
<p>Ya, sepenuhnya percuma. Anda hanya perlukan akaun Google dan pengesahan pantas laman web anda.</p>
<h3>Apa beza Search Console dengan Analytics?</h3>
<p>Search Console meliputi cara orang menemui anda dalam carian Google; Analytics meliputi apa yang mereka lakukan di laman anda. Gunakan kedua-duanya bersama.</p>
<h3>Bagaimana saya cari kemenangan kata kunci dalam GSC?</h3>
<p>Semak laporan Prestasi untuk pertanyaan di mana anda mendapat kedudukan di halaman dua — menambah baik halaman itu selalunya laluan terpantas kepada lebih trafik.</p>
<h3>Berapa kerap saya patut menyemak Search Console?</h3>
<p>Bulanan sudah cukup untuk kebanyakan, tambah selepas menerbitkan kandungan penting (untuk meminta pengindeksan) atau jika anda mengesyaki isu teknikal.</p>
<p>BrandKraf membantu perniagaan Malaysia mengembangkan trafik organik. Terokai <a href="/ms/guides/marketing-analytics">panduan analitik pemasaran</a> kami, <a href="/ms/guides/seo">panduan SEO</a> kami, atau <a href="/ms/contact">hubungi kami</a>.</p>$ms$
where slug = 'google-search-console-guide';
